function decodeB64Ascii(s) {
  // 快路径：宿主若暴露 Buffer，直接一次性解码（比逐字符循环快 1~2 个数量级）
  try {
    if (typeof Buffer !== "undefined" && Buffer && typeof Buffer.from === "function") {
      var buf = Buffer.from(s, "base64");
      if (buf && typeof buf.length === "number") return buf;
    }
  } catch (e) { }
  // 退路：查表 + 数组，最后统一转
  var B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  var map = {};
  for (var i = 0; i < B.length; i++) map[B.charAt(i)] = i;
  var len = s.length;
  var out = [];
  var buffer = 0;
  var bits = 0;
  for (var j = 0; j < len; j++) {
    var ch = s.charCodeAt(j);
    if (ch === 61) break; // '='
    var v = map[s.charAt(j)];
    if (v === undefined) continue;
    buffer = (buffer << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out.push((buffer >> bits) & 0xFF);
    }
  }
  return out;
}

function bytesToUtf8(bytes) {
  // 优先用平台 TextDecoder（原生实现，快且不占 JS 堆）
  try {
    if (typeof TextDecoder !== "undefined") {
      var arr = (bytes && typeof bytes.subarray === "function") ? bytes : new Uint8Array(bytes);
      return new TextDecoder("utf-8").decode(arr);
    }
  } catch (e) { }
  // 退路：分块拼接（比逐字符 += 快很多）
  var CHUNK = 8192;
  var parts = [];
  var cur = "";
  var i = 0;
  var n = bytes.length;
  while (i < n) {
    var b = bytes[i++];
    var cp = -1;
    if (b < 0x80) {
      cp = b;
    } else if (b >= 0xC0 && b < 0xE0) {
      cp = ((b & 0x1F) << 6) | (bytes[i++] & 0x3F);
    } else if (b >= 0xE0 && b < 0xF0) {
      cp = ((b & 0x0F) << 12) | ((bytes[i++] & 0x3F) << 6) | (bytes[i++] & 0x3F);
    } else {
      cp = ((b & 0x07) << 18) | ((bytes[i++] & 0x3F) << 12) | ((bytes[i++] & 0x3F) << 6) | (bytes[i++] & 0x3F);
      cp -= 0x10000;
      cur += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
      if (cur.length >= CHUNK) { parts.push(cur); cur = ""; }
      continue;
    }
    cur += String.fromCharCode(cp);
    if (cur.length >= CHUNK) { parts.push(cur); cur = ""; }
  }
  if (cur) parts.push(cur);
  return parts.join("");
}

