function getHtml() {
  if (__htmlCache === null) {
    __htmlCache = bytesToUtf8(decodeB64Ascii(HTML_B64));
  }
  return __htmlCache;
}

function buildTextResponse(mimeType, text) {
  return {
    action: "respond",
    response: {
      mimeType: mimeType,
      encoding: "UTF-8",
      statusCode: 200,
      reasonPhrase: "OK",
      headers: { "Cache-Control": "no-store" },
      text: text,
    },
  };
}

function buildFileResponse(mimeType, filePath, cacheSeconds) {
  var cc = cacheSeconds && cacheSeconds > 0 ? "max-age=" + cacheSeconds : "no-store";
  return {
    action: "respond",
    response: {
      mimeType: mimeType,
      encoding: "UTF-8",
      statusCode: 200,
      reasonPhrase: "OK",
      headers: { "Cache-Control": cc },
      filePath: filePath,
    },
  };
}

function resolvePathname(url) {
  var text = String(url || "").trim();
  if (!text) return null;
  if (text === HOST) return "/";
  if (text.indexOf(HOST + "/") !== 0) return null;
  var suffix = text.slice(HOST.length) || "/";
  var withoutHash = suffix.split("#")[0] || "/";
  var withoutQuery = withoutHash.split("?")[0] || "/";
  return withoutQuery || "/";
}

function mimeForPath(p) {
  var s = String(p || "").toLowerCase();
  if (/\.html?$/.test(s)) return "text/html";
  if (/\.css$/.test(s)) return "text/css";
  if (/\.js$/.test(s)) return "application/javascript";
  if (/\.json$/.test(s)) return "application/json";
  if (/\.png$/.test(s)) return "image/png";
  if (/\.jpe?g$/.test(s)) return "image/jpeg";
  if (/\.gif$/.test(s)) return "image/gif";
  if (/\.webp$/.test(s)) return "image/webp";
  if (/\.svg$/.test(s)) return "image/svg+xml";
  if (/\.mp4$/.test(s)) return "video/mp4";
  if (/\.webm$/.test(s)) return "video/webm";
  if (/\.mov$/.test(s)) return "video/quicktime";
  if (/\.mp3$/.test(s)) return "audio/mpeg";
  return "application/octet-stream";
}

function decodeParam(raw) {
  var s = String(raw || "");
  try {
    return decodeURIComponent(s);
  } catch (e) {
    return s;
  }
}

function Screen(ctx) {
  var UI = ctx.UI;
  var useState = ctx.useState;

  var sReady = useState("xs_ready", false);
  var sHtmlPath = useState("xs_html_path", "");
  var sNote = useState("xs_note", "");
  var sLog = useState("xs_log", "");
  var ready = sReady[0];
  var setReady = sReady[1];
  var htmlPath = sHtmlPath[0];
  var setHtmlPath = sHtmlPath[1];
  var note = sNote[0];
  var setNote = sNote[1];
  var logText = sLog[0];
  var setLog = sLog[1];

  var controller = ctx.createWebViewController("x_social_webview");

  function log(msg) {
    var line = "[" + new Date().toISOString().slice(11, 19) + "] " + String(msg);
    try { setLog(line); } catch (e) { }
    if (!VERBOSE_LOG) return;
    try {
      Tools.Files.write(STATE_DIR + "/_boot.log", line + "\n", true, "android").catch(function () { });
    } catch (e) { }
  }

  var injected = false;
  function injectBridge() {
    if (injected) return true;
    try {
      if (controller.removeJavascriptInterface) {
        try { controller.removeJavascriptInterface(INTERFACE_NAME); } catch (e) { }
      }
      controller.addJavascriptInterface(INTERFACE_NAME, hostInterface);
      injected = true;
      return true;
    } catch (e) {
      log("inject fail " + String(e));
      return false;
    }
  }

  async function bootWebView() {
    if (ready) return;
    var t0 = Date.now();
    try {
      setNote("正在准备界面…");
      // 先把 HTML 的落盘路径准备好（按版本号缓存，避免每次启动都重写 75KB）
      var target = STATE_DIR + "/" + HTML_OUTPUT_NAME;
      var versionFile = STATE_DIR + "/_" + HTML_OUTPUT_NAME + ".ver";
      var usable = false;
      if (htmlPath) usable = true;
      if (!usable) {
        try {
          var vres = await Tools.Files.read(versionFile, "android");
          var vtxt = vres && (vres.content !== undefined ? vres.content : vres.data);
          var exists = await Tools.Files.exists(target, "android");
          if (String(vtxt || "").trim() === HTML_VERSION && exists && exists.exists) usable = true;
        } catch (e) { }
      }
      if (usable) {
        setHtmlPath(target);
        log("复用缓存 " + (Date.now() - t0) + "ms");
      } else {
        var html = getHtml();
        log("解码 " + html.length + " chars / " + (Date.now() - t0) + "ms");
        try { await Tools.Files.mkdir(STATE_DIR, true, "android"); } catch (e) { }
        try {
          await Tools.Files.write(target, html, false, "android");
          setHtmlPath(target);
          try { await Tools.Files.write(versionFile, HTML_VERSION, false, "android"); } catch (e2) { }
          log("落盘 -> " + target + " / " + (Date.now() - t0) + "ms");
        } catch (e) {
          setHtmlPath("");
          log("落盘失败(改用内存响应) " + String(e));
        }
      }
      injectBridge();
      setNote("");
      setReady(true);
      log("ready " + (Date.now() - t0) + "ms");
    } catch (e) {
      setNote("加载失败: " + String(e));
      log("boot fail " + String(e));
    }
  }

  var pending = {};
  var seq = 0;

  // ================================================================
  // 桥接实现（v12）
  //
  // 三条通道同时开着，谁先到用谁：
  //  ① 桥方法直接 return（Promise）—— 与 yuxue_phone / wechat_call 一致，宿主支持时最快
  //  ② resultStore + pollResult(id) —— 同步轮询兜底，不依赖 Promise 能否跨桥返回
  //  ③ 页面侧 __xResolve 回推 —— 老宿主兼容（在页面里实现）
  //
  // 注意：绝不能在桥回调里同步 evaluateJavascript（WebView 线程互锁，静默失败）。
  // ================================================================
  var resultStore = {};

  function normalizeResult(r) {
    if (r === undefined || r === null) return { success: false, message: "工具无返回" };
    if (typeof r === "string") {
      try { return JSON.parse(r); } catch (e) { return { success: true, data: r }; }
    }
    return r;
  }
  function putResult(cid, res) {
    var payload = normalizeResult(res);
    if (!payload || typeof payload !== "object") payload = { success: true, data: payload };
    var text;
    try { text = JSON.stringify(payload); } catch (e) { text = '{"success":false,"message":"serialize failed"}'; }
    try { resultStore[cid] = text; } catch (e) { }
  }
  function pollResult(callId) {
    var cid = String(callId || "");
    var v = resultStore[cid];
    if (v === undefined || v === null) return "";
    delete resultStore[cid];
    return String(v);
  }
  // ================================================================
  // 【关键·本轮修复】宿主把 JS 侧调用的实参统一打包成「一个数组」再交给 handler：
  //   invokeAction(actionId, payload) → handler(payload)
  // 也就是说桥接方法实际只会收到 **一个** 形参（内容 = 实参数组）。
  // 之前这里写成 callTool(callId, toolName, paramsJson) 三个形参时，
  // 第一个形参拿到的是整个数组 → 工具名/参数全丢 →
  //   个人主页加载失败、发帖失败、图片视频上传失败（三个症状一个根因）。
  // 参考包（yuxue_phone / GRANDIA）一律只声明一个形参并自行解包，这里对齐。
  // ================================================================
  function unwrapArg(raw) {
    if (Array.isArray(raw) && raw.length === 1) return raw[0];
    return raw;
  }
  function parsePayload(raw) {
    var v = raw;
    if (Array.isArray(v) && v.length === 1) v = v[0];
    if (typeof v === "string" && v) {
      var parsed = null;
      try { parsed = JSON.parse(v); } catch (e) { parsed = null; }
      if (parsed !== null && parsed !== undefined) {
        v = parsed;
        if (Array.isArray(v) && v.length === 1) v = v[0];
        if (typeof v === "string") {
          try { v = JSON.parse(v); } catch (e2) { }
        }
      }
    }
    if (v && typeof v === "object" && !Array.isArray(v)) return v;
    return {};
  }
  // 回给页面统一用 JSON 字符串（对齐参考包的 serialize()，最不容易被宿主弄丢）
  function serializeResult(r) {
    if (r === undefined || r === null) return JSON.stringify({ success: false, message: "空返回" });
    if (typeof r === "string") {
      var c = r.charAt(0);
      if (c === "{" || c === "[") return r;
      return JSON.stringify({ success: true, data: r });
    }
    try { return JSON.stringify(r); } catch (e) { return JSON.stringify({ success: false, message: "结果序列化失败" }); }
  }
  function beginToolCall(callId, toolName, params) {
    var cid = String(callId || "");
    /* 【关键·修复·发帖卡界面】**立刻回执**，不要把 Promise 返回给宿主。
       宿主的 JS 桥接（C1365r.postMessage）是单向的，返回值靠
       evaluateJavascript 回推；宿主会 await 这个 JS handler 的返回值。
       旧实现返回 `p.then(...)`（一个 Promise）→ 宿主一直 await 到
       工具真正跑完 → 期间宿主 UI 帧被挂起 → 整个界面冻住。
       现在立即返回 "1"（= "无直接结果"），真实结果写进 resultStore，
       页面用 pollResult 轮询取回（通道②，页面本就支持）。 */
    try {
      var p = ctx.callTool(String(toolName || ""), params || {});
      if (p && typeof p.then === "function") {
        p.then(function (r) {
          putResult(cid, r);
        }, function (e) {
          putResult(cid, { success: false, message: String((e && e.message) || e) });
        });
        return "1";
      }
      putResult(cid, p);
      return "1";
    } catch (e) {
      putResult(cid, { success: false, message: "callTool 异常: " + String((e && e.message) || e) });
      return "1";
    }
  }
  function beginPickMedia(callId, kind, multiple) {
    var cid = String(callId || "");
    /* 立刻回执（理由同 beginToolCall）。注意：文件选择器本身是异步的，
       这里只是不再把 Promise 交回宿主去 await。 */
    try {
      if (typeof ctx.openFilePicker !== "function") {
        putResult(cid, { cancelled: true, files: [], message: "宿主不支持文件选择器" });
        return "1";
      }
      // 只用宿主已验证的字段 picker + allowMultiple（与 sticker_manager 官方包一致）
      var r = ctx.openFilePicker({ picker: String(kind || "image"), allowMultiple: multiple !== false });
      if (r && typeof r.then === "function") {
        r.then(function (v) {
          putResult(cid, v || { cancelled: true, files: [] });
        }, function (e) {
          putResult(cid, { cancelled: true, files: [], message: String((e && e.message) || e) });
        });
        return "1";
      }
      putResult(cid, r || { cancelled: true, files: [] });
      return "1";
    } catch (e) {
      putResult(cid, { cancelled: true, files: [], message: String((e && e.message) || e) });
      return "1";
    }
  }

  // ================================================================
  // 【新增·v20】UI 帧直连对话（对齐 com.operit.yuxue_phone 的做法）
  //
  // 为什么必须在 UI 帧做：
  //   绑定对话通常就是**当前正在跑的会话**。在包运行时用
  //   Tools.Chat.sendMessage 往里发消息，会撞上宿主的 busy 保护
  //   （"Previous message is still being processed"）而失败，
  //   于是消息没进对话，AI 永远不会回复。
  //   yuxue_phone 正是把 sendMessage / getMessages 放在 UI 帧里调用的，
  //   那里不受该限制。本插件照此实现。
  //
  // 通道说明：
  //   sendMessage → 消息进入绑定对话，AI 开始生成回复
  //   getMessages → 读回 AI 的新回复，回填到 X 私信
  // ================================================================
  function beginChatSend(callId, chatId, text) {
    var cid = String(callId || "");
    /* 【关键·修复·发帖卡界面】这里**必须立刻回执**，绝不能把
       Tools.Chat.sendMessage 的 Promise 直接返回给 WebView。
       原因（实测定位）：
         宿主把 WebView → UI 帧的桥接调用实现成**同步等待**，
         而底层 send_message_to_ai 要等 AI 跑完**一整轮对话**才 resolve。
         于是 WebView 的 JS 线程会被这一整轮对话整个卡住 →
         页面停止渲染、触摸无响应 → 用户看到「发帖后卡在当前界面不动」；
         退出侧边栏后一切正常，也正是因为那一轮在后台跑完了。
       改成：立即返回 "1"，真实结果写进 resultStore，
       页面用 pollResult 轮询取回（这本来就是三通道设计里的通道②，
       通道①只是"宿主支持时最快"，而这里恰恰是"慢到把界面拖死"）。 */
    function done(v) {
      putResult(cid, v);
      return "1";
    }
    try {
      if (typeof Tools === "undefined" || !Tools || !Tools.Chat ||
          typeof Tools.Chat.sendMessage !== "function") {
        return done({ success: false, message: "宿主不支持对话发送" });
      }
      var p = Tools.Chat.sendMessage(String(text || ""), chatId || undefined, undefined, undefined, {
        runtime: "main",
        hide_user_message: false,
        notify_reply: true,
        disable_warning: true,
        persist_turn: true
      });
      if (p && typeof p.then === "function") {
        // 后台跑：结果回来时再放进 resultStore，页面轮询取
        p.then(function (r) {
          putResult(cid, { success: true, data: r, message: "已发送到对话" });
        }, function (e) {
          putResult(cid, { success: false, message: String((e && e.message) || e) });
        });
        return "1";
      }
      return done({ success: true, data: p, message: "已发送到对话" });
    } catch (e) {
      return done({ success: false, message: String((e && e.message) || e) });
    }
  }
  function beginChatHistory(callId, chatId, limit) {
    var cid = String(callId || "");
    /* 同样立刻回执（理由同 beginToolCall：宿主会 await JS handler 的返回值） */
    try {
      if (typeof Tools === "undefined" || !Tools || !Tools.Chat ||
          typeof Tools.Chat.getMessages !== "function") {
        putResult(cid, { success: false, message: "宿主不支持读取对话" });
        return "1";
      }
      var lim = Math.max(1, Math.min(100, Number(limit || 20)));
      var p = Tools.Chat.getMessages(String(chatId || ""), { order: "desc", limit: lim });
      if (p && typeof p.then === "function") {
        p.then(function (r) {
          putResult(cid, { success: true, data: r, message: "读取完成" });
        }, function (e) {
          putResult(cid, { success: false, message: String((e && e.message) || e) });
        });
        return "1";
      }
      putResult(cid, { success: true, data: p, message: "读取完成" });
      return "1";
    } catch (e) {
      putResult(cid, { success: false, message: String((e && e.message) || e) });
      return "1";
    }
  }

  var hostInterface = {
    // 注意：所有方法都只声明一个形参（宿主只会递给我们一个「实参数组」）
    callTool: function (payload) {
      var req = parsePayload(payload);
      return beginToolCall(String(req.id || ""), String(req.name || ""), req.params || {});
    },
    // 【新增】UI 帧直发到绑定对话（绕开包运行时的 busy 保护）
    chatSend: function (payload) {
      var req = parsePayload(payload);
      return beginChatSend(String(req.id || ""), String(req.chatId || ""), String(req.text || ""));
    },
    // 【新增】UI 帧直读对话历史
    chatHistory: function (payload) {
      var req = parsePayload(payload);
      return beginChatHistory(String(req.id || ""), String(req.chatId || ""), Number(req.limit || 20));
    },
    pickMedia: function (payload) {
      var req = parsePayload(payload);
      return beginPickMedia(String(req.id || ""), String(req.kind || "image"), req.multiple !== false);
    },
    pollResult: function (callId) {
      return pollResult(String(unwrapArg(callId) || ""));
    },
    toast: function (msg) {
      try {
        if (typeof ctx.showToast === "function") ctx.showToast(String(unwrapArg(msg) || ""));
      } catch (e) { }
      return "1";
    },
    log: function (msg) {
      log("page: " + String(unwrapArg(msg) || "").substring(0, 160));
      return "1";
    },
    ping: function () { return "pong"; },
    version: function () { return "6.0.0"; },
  };

  function handleResourceRequest(request) {
    try {
      var pathname = resolvePathname(request && request.url);
      if (!pathname) return { action: "allow" };
      if (pathname === "/" || pathname === "/index.html" || pathname === "/app") {
        if (htmlPath) return buildFileResponse("text/html", htmlPath);
        return buildTextResponse("text/html", getHtml());
      }
      if (pathname === "/file") {
        var url = String((request && request.url) || "");
        var m = /[?&]path=([^&#]+)/.exec(url);
        if (!m) return buildTextResponse("text/plain", "bad request");
        var fp = decodeParam(m[1]);
        if (fp.charAt(0) === "/") return buildFileResponse(mimeForPath(fp), fp, 3600);
        return buildTextResponse("text/plain", "bad path");
      }
      return buildTextResponse("text/html", "<!doctype html><meta charset=utf-8><body style='font-family:sans-serif;padding:24px'>404 " + pathname + "</body>");
    } catch (e) {
      return { action: "allow" };
    }
  }

  function handleNavigation(request) {
    return { action: "allow" };
  }

  function handleLifecycle(event) {
    try {
      if (event && event.type === "disposed") {
        injected = false;
        if (controller.removeJavascriptInterface) {
          controller.removeJavascriptInterface(INTERFACE_NAME);
        }
      }
    } catch (e) { }
  }

  return UI.Box({ fillMaxSize: true, backgroundColor: "#ffffff", onLoad: bootWebView }, [
    ready
      ? UI.WebView({
          fillMaxSize: true,
          controller: controller,
          key: "x_social_webview_main",
          url: HOST + "/",
          nestedScrollInterop: true,
          javaScriptEnabled: true,
          domStorageEnabled: true,
          databaseEnabled: false,
          supportZoom: false,
          useWideViewPort: true,
          loadWithOverviewMode: true,
          // 首屏不需要手势就能播，但关掉可以减少初始化开销
          mediaPlaybackRequiresUserGesture: false,
          mixedContentMode: "alwaysAllow",
          allowFileAccess: true,
          allowFileAccessFromFileURLs: true,
          onLifecycleEvent: handleLifecycle,
          onShouldOverrideUrlLoading: handleNavigation,
          onInterceptRequest: handleResourceRequest,
        })
      : UI.Column({ padding: 20, spacing: 10, verticalAlignment: "center" }, [
          UI.Text({ text: "X", fontSize: 30, bold: true, color: "#1d9bf0" }),
          UI.Text({ text: note || "正在加载 X…", fontSize: 13, color: "#536471" }),
          UI.Text({ text: logText, fontSize: 10, color: "#a0a8b0" }),
          UI.Button({
            text: "重新加载",
            containerColor: "#1d9bf0",
            contentColor: "#ffffff",
            onClick: function () {
              injected = false;
              setHtmlPath("");
              setNote("");
              setReady(false);
              bootWebView();
            },
          }),
        ]),
  ]);
}
